"use client";

import { useState, type ReactNode } from "react";
import { Breadcrumbs, Button, MediaUpload, PageTitleToolbar, RadioWithLabel, SelectOption, TextArea, TextField } from "@forge-ui-official/core";

export interface ProductDraft {
  name: string;
  sku: string;
  category: string;
  brand: string;
  tags: string;
  description: string;
  price: string;
  listPrice: string;
  cost: string;
  stock: string;
  alertStock: string;
  taxRate: string;
  weight: string;
  origin: string;
  shipping: string;
