    profile={{ name: "张宁", role: "运营负责人", avatar: "/images/team/edward-allen.png" }}
    topbarLeftMode="search"
    searchPlaceholder="搜索设置项"
    notifications={1}
  >
    {children}
  </AppLayout>;
}

